ini_set('display_errors','0');error_reporting(E_ALL);header('Content-Type: application/json; charset=utf-8');$R=__DIR__.'/..';require "$R/lib/Db.php";require "$R/lib/Jwt.php";$C=require "$R/config.php";$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m))exit(json_encode(['error'=>'توکن نامعتبر است']));$p=Jwt::verify(trim($m[1]),$C['jwt_secret']);if(!$p)exit(json_encode(['error'=>'توکن نامعتبر است']));$u=Db::one("SELECT u.id,u.is_active,r.title role_title,r.is_admin FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?",[$p['sub']]);if(!$u||!$u['is_active'])exit(json_encode(['error'=>'کاربر نامعتبر است']));$b=json_decode(file_get_contents('php://input'),true)?:[];$name=trim((string)($b['name']??'خط غیر فعال'));$status=trim((string)($b['status']??'غیرفعال'));if($name==='')$name='خط غیر فعال';$code='N/A-'.date('ymd').'-'.random_int(1000,9999);$cols=Db::all("SELECT COLUMN_NAME,DATA_TYPE,COLUMN_DEFAULT,IS_NULLABLE,EXTRA FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='lines' ORDER BY ORDINAL_POSITION");$v=[];foreach($cols as $c){$n=$c['COLUMN_NAME'];if(stripos($c['EXTRA'],'auto_increment')!==false||$c['COLUMN_DEFAULT']!==null||$c['IS_NULLABLE']==='YES')continue;if(in_array($n,['code','line_code','number'],true))$v[$n]=$code;elseif(in_array($n,['title','name'],true))$v[$n]=$name;elseif(in_array($n,['description','origin'],true))$v[$n]=$status;elseif(in_array($n,['destination'],true))$v[$n]=$name;elseif(in_array($n,['is_active','active','enabled'],true))$v[$n]=0;elseif(in_array($n,['is_auto_missing','auto_generated'],true))$v[$n]=1;elseif(str_contains(strtolower($c['DATA_TYPE']),'int')||str_contains(strtolower($c['DATA_TYPE']),'decimal')||str_contains(strtolower($c['DATA_TYPE']),'float'))$v[$n]=0;elseif(str_contains(strtolower($c['DATA_TYPE']),'date')||str_contains(strtolower($c['DATA_TYPE']),'time'))$v[$n]=date('Y-m-d H:i:s');else $v[$n]=$name;}if(!array_intersect(array_keys($v),['code','line_code','number'])){htt